using System;
using UnityEngine;

namespace Game.World
{
    /// <summary>
    /// Baked point instances of a region (generated by the importer, ADR 0012), drawn by <see cref="WorldInstances"/>.
    /// Matrices are in the region root's space (x east, y absolute height, z north). Cells (64 m) hold runs of one
    /// prototype each, so a run is one contiguous array range.
    /// </summary>
    public sealed class WorldInstanceSet : ScriptableObject
    {
        [Serializable]
        public sealed class Prototype
        {
            public string name;
            [Tooltip("LOD meshes, nearest first (e.g. LOD0, LOD1, impostor)")]
            public Mesh[] lods = Array.Empty<Mesh>();
            [Tooltip("Distance (m, at lodBias 1) where each LOD ends; the last one is the cull distance")]
            public float[] lodEndM = Array.Empty<float>();
            [Tooltip("Index into materials of submesh 0 of each LOD")]
            public int[] materialStart = Array.Empty<int>();
            [Tooltip("Bit l set = LOD l casts shadows")]
            public int shadowLodMask;
            public int count;
        }

        [Serializable]
        public struct Cell
        {
            public Bounds bounds;
            public int runStart, runCount;
        }

        [Serializable]
        public struct Run
        {
            public int prototype, start, count;
        }

        public Prototype[] prototypes = Array.Empty<Prototype>();
        public Material[] materials = Array.Empty<Material>();
        public Cell[] cells = Array.Empty<Cell>();
        public Run[] runs = Array.Empty<Run>();
        public Matrix4x4[] matrices = Array.Empty<Matrix4x4>();
    }
}
